const PATHS={home:'M6 3h12a3 3 0 013 3v12a3 3 0 01-3 3H6a3 3 0 01-3-3V6a3 3 0 013-3zm0 6h12M9 13h3m-3 4h6',network:'M12 3v5m0 0L5 13m7-5l7 5M3 18h6v3H3zm12 0h6v3h-6zM9 11h6v3H9z',image:'M3 5a2 2 0 012-2h14a2 2 0 012 2v14a2 2 0 01-2 2H5a2 2 0 01-2-2zM3 17l5-5 4 4 3-3 6 6M8 9h.01',send:'M22 2 11 13M22 2l-7 20-4-9-9-4z',handshake:'M2 12l4-4 3 2 4-3 5 3 4-1m-20 3 5 6 4-2 5 3 5-5M8 16l3-3m1 5 3-3',chart:'M4 20V11m5 9V5m5 15v-7m5 7V3M2 20h20',settings:'M12 8a4 4 0 100 8 4 4 0 000-8zM19 12a7 7 0 00-.1-1l2-1.6-2-3.5-2.4 1A7 7 0 0015 6l-.4-2.6h-4L10 6a7 7 0 00-1.5.9l-2.4-1-2 3.5 2 1.6a7 7 0 000 2l-2 1.6 2 3.5 2.4-1a7 7 0 001.5.9l.4 2.6h4l.4-2.6a7 7 0 001.5-.9l2.4 1 2-3.5-2-1.6a7 7 0 00.1-1z',download:'M12 3v13m0 0 5-5m-5 5-5-5M4 19v2h16v-2',refresh:'M20 11a8 8 0 00-14-5L4 8m0-5v5h5m-5 5a8 8 0 0014 5l2-2m0 5v-5h-5',plus:'M12 5v14M5 12h14',search:'M11 19a8 8 0 110-16 8 8 0 010 16zm6-2 5 5',check:'m5 12 5 5L20 7',chevron:'m9 18 6-6-6-6',users:'M16 21v-2a4 4 0 00-4-4H6a4 4 0 00-4 4v2m7-10a4 4 0 110-8 4 4 0 010 8zm13 10v-2a4 4 0 00-3-3.87M16 3a4 4 0 010 7.75',calendar:'M7 3v4m10-4v4M3 10h18M5 5h14a2 2 0 012 2v12a2 2 0 01-2 2H5a2 2 0 01-2-2V7a2 2 0 012-2z',clock:'M12 3a9 9 0 100 18 9 9 0 000-18zm0 5v5l3 2',shield:'M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z',external:'M14 4h6v6M20 4 10 14M20 14v5a1 1 0 01-1 1H5a1 1 0 01-1-1V5a1 1 0 011-1h5',pause:'M7 5v14m10-14v14',close:'M6 6l12 12M18 6 6 18',file:'M6 2h8l5 5v15H6a2 2 0 01-2-2V4a2 2 0 012-2zm8 0v6h6',heart:'M20 8c0 6-8 12-8 12S4 14 4 8a5 5 0 018-3 5 5 0 018 3z',spark:'M12 2 9 9l-7 3 7 3 3 7 3-7 7-3-7-3z',link:'M10 13a5 5 0 007 0l3-3a5 5 0 00-7-7l-2 2m3 6a5 5 0 00-7 0l-3 3a5 5 0 007 7l2-2',filter:'M4 7h16M7 12h10m-7 5h4',info:'M12 11v6m0-10v1M12 22a10 10 0 110-20 10 10 0 010 20',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7-10-7-10-7zM12 9a3 3 0 100 6 3 3 0 000-6'};
const telegramMark=`<svg class="telegram-mark" viewBox="0 0 48 48" aria-hidden="true"><circle cx="24" cy="24" r="23" fill="#2AABEE"/><path fill="#fff" d="M36.5 13.3 30.3 36c-.47 1.6-1.75 2-3.2 1.23l-8.25-6.1-4.06 3.9c-.45.45-.83.83-1.7.83l.6-8.48L29.2 17.4c.67-.59-.14-.92-1.04-.32l-19.2 12.1-8.3-2.59c-1.8-.57-1.83-1.8.38-2.67L33.4 11.45c1.5-.56 2.82.36 2.33 1.85Z" transform="translate(4 0) scale(.9)"/></svg>`;
const icon=n=>`<svg aria-hidden="true" viewBox="0 0 24 24"><path d="${PATHS[n]||PATHS.info}"/></svg>`;
const E=s=>String(s??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#39;');
const A=(s)=>Array.isArray(s)?s:[];
const fmt=n=>n==null||n===''?'—':new Intl.NumberFormat('fr-FR').format(Number(n));
const date=t=>t?new Date(Number(t)*1000).toLocaleString('fr-FR',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}):'—';
const badge=(text,cls='')=>`<span class="badge ${cls}">${E(text)}</span>`;
const btn=(name,label,cls='',attrs='')=>`<button class="btn ${cls}" data-action="${E(name)}" ${attrs}>${label}</button>`;
const field=(name,label,kind='text',value='',opts='')=>`<div class="field"><label for="f-${E(name)}">${E(label)}</label>${kind==='textarea'?`<textarea id="f-${E(name)}" class="textarea" name="${E(name)}" ${opts}>${E(value)}</textarea>`:kind==='select'?`<select id="f-${E(name)}" class="select" name="${E(name)}">${value}</select>`:`<input id="f-${E(name)}" class="input" name="${E(name)}" type="${E(kind)}" value="${E(value)}" ${opts}>`}</div>`;
const options=(rows,value=null)=>rows.map(([v,l])=>`<option value="${E(v)}"${String(value)===String(v)?' selected':''}>${E(l)}</option>`).join('');
const channelOptions=(onlyAdmin=false,value=null)=>options(A(S.channels).filter(c=>!onlyAdmin||c.can_post).map(c=>[c.id,c.title]),value);
const mediaOptions=(onlyApproved=true)=>A(S.media).filter(m=>!onlyApproved||(m.reviewed&&['own','partner','licensed'].includes(m.rights)&&!m.revoked)).map(m=>[m.id,m.name]);
const stat=(name,value,foot,ic,tint='#78e5cf')=>`<div class="glass stat-card" style="--tint:${tint};--glow:${tint}"><div class="stat-row"><span class="stat-name">${E(name)}</span><span class="stat-icon">${icon(ic)}</span></div><div class="stat-num">${fmt(value)}</div><div class="stat-foot">${E(foot)}</div></div>`;
const empty=(title,desc,action='')=>`<div class="empty"><div class="empty-illustration">${icon('spark')}</div><h3>${E(title)}</h3><p>${E(desc)}</p>${action}</div>`;
const head=(title,subtitle,actions='',eyebrow='ESPACE DE TRAVAIL')=>`<div class="page-header"><div><div class="eyebrow">${E(eyebrow)}</div><h1>${E(title)}</h1><div class="subtitle">${E(subtitle)}</div></div><div class="header-actions">${actions}</div></div>`;
const table=(headers,rows)=>`<div class="table-shell"><table class="table"><thead><tr>${headers.map(h=>`<th>${E(h)}</th>`).join('')}</tr></thead><tbody>${rows.join('')||`<tr><td colspan="${headers.length}" class="muted" style="padding:35px;text-align:center">Aucune donnée pour le moment.</td></tr>`}</tbody></table></div>`;
const row=(cells)=>`<tr>${cells.map(c=>`<td>${c}</td>`).join('')}</tr>`;
const info=(label,val)=>`<div class="info-line"><span>${E(label)}</span><strong>${val}</strong></div>`;
const avatar=(row,big=false)=>`<span class="avatar ${big?'avatar-xl':''}"><span class="avatar-fallback">${E((row.title||'?').trim()[0].toUpperCase())}</span><img class="channel-avatar-img" loading="lazy" alt="" src="/api/avatar/${encodeURIComponent(row.id)}"></span>`;
const TYPES={broadcast:'Canal',supergroup:'Supergroupe',group:'Groupe'};
const ROLES={owner:'Propriétaire',admin:'Administrateur',member:'Membre',read_only:'Lecture seule',unknown:'À synchroniser'};
const RIGHTS={own:'Personnel',partner:'Partenaire autorisé',licensed:'Sous licence',unverified:'À valider',forbidden:'Interdit',protected:'Protégé'};
const STATES={draft:'Brouillon',pending:'En attente',scheduled:'Programmé',running:'En cours',completed:'Terminé',failed:'Échec',cancelled:'Annulé',unknown:'Incertain'};
let S={channels:[],media:[],sources:[],tasks:[],events:[],network_links:[],exchanges:[],partners:[],observations:[],metrics:[],task_media:[],connected:false,identity:'Non connecté',auth_state:'credentials',blur:true,engine:false,api_id:'',auto_watch:false,interval:'60'};
const U={route:'home',channel:null,search:'',networkFilter:'all',sourceSearch:'',mediaSearch:'',mediaFilter:'all',selectedMedia:new Set(),mediaThumb:new Map(),mediaLimit:60,importChannel:null,importKind:'all',previewMessageIds:new Set(),importPermissions:false,pendingBrowse:null,composeMedia:new Set(),draft:{},activeModal:null,selectedExchange:null,selectedPartner:null,help:false,partnerMessages:[],partnerError:'',revealedMedia:new Set(),blurStrength:parseInt((()=>{try{return localStorage.getItem('telepilot_blur')}catch{return '18'}})()||'18',10)};
let API={};
let lastSnapshotKey='';
function toast(text,error=false){const root=document.getElementById('toast-root'), el=document.createElement('div');el.className='toast'+(error?' error':'');el.textContent=String(text);root.appendChild(el);setTimeout(()=>el.remove(),5600)}
function handleResponse(p){
  if(!p.ok){if(p.name==='partner_messages'){U.partnerError=p.data||'Discussion inaccessible.';U.partnerMessages=[];render();}toast(p.data||'Opération interrompue',true);return}
  if(p.name==='browse_channel_media')showPicker(p.data);
  else if(p.name==='recent')showRecent(p.data);
  else if(p.name==='import_channel_media'||p.name==='import_telegram')toast('Importation démarrée. Suivez sa progression en bas.');
  else if(p.name==='resolve_channel')toast('Canal ajouté à votre réseau.');
  else if(p.name==='sync_channels')toast('Synchronisation terminée.');
  else if(p.name==='create_community'){toast('Canal ou groupe créé.');U.channel=p.data.id;navigate('network');}
  else if(p.name==='partner_messages'){U.partnerError='';U.partnerMessages=A(p.data);render();}
  else if(p.name==='partner_reply'){toast('Réponse envoyée.');run('partner_messages',{partner_id:U.selectedPartner});}
  else if(p.name==='media_thumbnail'&&p.data?.image){U.mediaThumb.set(p.data.media_id,p.data.image);const el=document.querySelector(`[data-media-img="${p.data.media_id}"]`);if(el)el.innerHTML=`<img alt="Aperçu" loading="lazy" src="${p.data.image}">`}
}
async function loadState(){
  try {
    const response=await fetch('/api/state',{credentials:'same-origin',cache:'no-store'});
    if(!response.ok)throw new Error(`État serveur indisponible : ${response.status}`);
    const data=await response.json();
    const signature=JSON.stringify(data);
    S=data;
    if(signature===lastSnapshotKey){updateBars();return;}
    const modal=document.getElementById('modal-backdrop');
    const focus=document.activeElement;
    if(!modal.classList.contains('hidden')||(focus&&['INPUT','TEXTAREA','SELECT'].includes(focus.tagName))){updateBars();return}
    lastSnapshotKey=signature;
    render();
  }catch(err){if(!loadState.warned){toast('Connexion au serveur local interrompue.',true);loadState.warned=true}}
}
async function run(name,args={}){
  try{
    const res=await fetch('/api/command',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-TelePilot-Request':'1'},body:JSON.stringify({name,args})});
    const payload=await res.json();
    const response={name,ok:res.ok&&payload.ok,data:payload.data||payload.error};
    handleResponse(response);
    await loadState();
    return response;
  }catch(err){toast('Erreur réseau locale : '+err.message,true);return {ok:false,data:err.message}}
}
async function importLocalFiles(){
  const input=document.createElement('input');input.type='file';input.multiple=true;input.accept='image/*,video/*';
  input.addEventListener('change',async()=>{
    const files=[...input.files];
    if(!files.length)return;
    toast(`${files.length} fichier(s) sélectionné(s). Importation en cours…`);
    for(const file of files){
      try{
        const res=await fetch('/api/upload',{method:'POST',credentials:'same-origin',headers:{'X-TelePilot-Request':'1','X-File-Name':encodeURIComponent(file.name),'Content-Type':'application/octet-stream'},body:file});
        const data=await res.json();
        toast(data.ok?`${file.name} ajouté à la médiathèque`:`${file.name} : ${data.data||data.error}`,!data.ok);
      }catch(err){toast(`${file.name} : ${err.message}`,true)}
    }
    await loadState();
  },{once:true});input.click();
}
function groupOf(route){return ROUTES.find(g=>g.items.some(i=>i[0]===route))}
function navigate(route){if(route==='settings'||ROUTES.some(g=>g.items.some(i=>i[0]===route))){U.route=route;U.search='';U.mediaSearch='';U.sourceSearch='';document.getElementById('main-scroll').scrollTop=0;render()}}
function nav(){
  const locked=!S.connected;
  document.body.classList.toggle('is-locked',locked);
  const active=groupOf(U.route)?.label;
  document.getElementById('primary-nav').innerHTML=ROUTES.map(g=>`<button class="nav-item ${active===g.label?'active':''}" data-route="${g.items[0][0]}"><span class="nav-icon">${icon(g.icon)}</span><span class="nav-label">${E(g.label)}</span></button>`).join('');
  document.getElementById('secondary-nav').innerHTML=`<button class="nav-item ${U.route==='settings'?'active':''}" data-route="settings"><span class="nav-icon">${icon('settings')}</span>Préférences</button>`;
  document.getElementById('account-label').textContent=S.connected?S.identity:'Telegram';
  document.getElementById('account-subtitle').textContent=S.connected?'Connecté':'En attente';
  const pill=document.getElementById('connection-pill');pill.classList.toggle('online',!!S.connected);pill.lastElementChild.textContent=S.connected?'Connecté':'Hors ligne';
  const group=groupOf(U.route), routeTitle=U.route==='settings'?'Préférences':group?.items.find(i=>i[0]===U.route)?.[1];
  document.getElementById('breadcrumbs').innerHTML=`<span>${E(group?.label||'TelePilot')}</span><span class="crumb-sep">/</span><strong>${E(routeTitle||'Accueil')}</strong>`;
}
function subnav(){const group=groupOf(U.route);return group&&group.items.length>1?`<div class="pills" style="margin-bottom:22px">${group.items.map(([route,title])=>`<button data-route="${route}" class="chip ${U.route===route?'active':''}">${E(title)}</button>`).join('')}</div>`:''}
function render(){
  nav();let p='';
  try {
    if(!S.connected){p=onboarding();}
    else switch(U.route){
      case 'home':p=home();break;case 'network':p=network();break;case 'organisation':p=organisation();break;
      case 'sources':p=sources();break;case 'library':p=library();break;case 'studio':p=studio();break;
      case 'queue':p=queue();break;case 'calendar':p=calendar();break;case 'rules':p=rules();break;
      case 'partners':p=partners();break;case 'exchanges':p=exchanges();break;case 'assistant':p=assistant();break;
      case 'statistics':p=statistics();break;case 'watch':p=watch();break;case 'activity':p=activity();break;
      case 'settings':p=settings();break;default:p=home();
    }
  }catch(error){console.error('Render',error);p=empty('Affichage indisponible',String(error));}
  document.getElementById('page').innerHTML=p;
  document.getElementById('page').classList.toggle('page-onboarding',!S.connected);
  document.getElementById('page').style.setProperty('--blur-strength',`${Math.max(0,Math.min(32,U.blurStrength))}px`);
  updateBars();
  if(S.connected&&U.route==='library')requestThumbnails();
}
function updateBars(){const candidates=A(S.tasks).filter(t=>t.kind==='import'&&['running','pending','scheduled'].includes(t.state));candidates.sort((a,b)=>Number(b.created_at)-Number(a.created_at));const t=candidates[0],el=document.getElementById('import-banner');if(!t){el.classList.add('hidden');return}let payload={};try{payload=JSON.parse(t.payload)}catch{}const mx=Number(payload.maximum||0),n=Number(t.progress||0);el.classList.remove('hidden');el.innerHTML=`<span style="color:#78e5cf">${icon('download')}</span><div><strong>${E(t.title)}</strong><small style="display:block">${t.paused?'En pause · ':''}${fmt(payload.downloaded||0)} téléchargés · ${fmt(payload.skipped||0)} ignorés</small></div><div class="progress-track"><div class="progress-bar" style="width:${mx?Math.min(100,100*n/mx):36}%"></div></div>${btn('pause-import',t.paused?'Reprendre':'Pause','sm',`data-id="${E(t.id)}"`)}${btn('cancel-import','Arrêter','sm ghost',`data-id="${E(t.id)}"`)}${btn('show-library','Médiathèque','sm')}`}
function onboarding(){
  const stage=S.auth_state||'credentials';
  const steps={credentials:'Identifiants',phone:'Téléphone',code:'Vérification',password:'Sécurité'};
  const body=stage==='credentials'?`${field('api_id','API ID','text',S.api_id||'','autocomplete="off" inputmode="numeric" placeholder="ID Telegram" required')}${field('api_hash','API Hash','password','','autocomplete="off" placeholder="Clé API Telegram" required')}<label class="check-row"><input type="checkbox" name="remember" checked> Conserver la clé dans le trousseau macOS</label><button class="btn primary w-full" type="submit" data-auth="configure">Continuer <span>→</span></button><button class="link-text" type="button" data-action="telegram-api">Où trouver mes identifiants ?</button>`:
  stage==='phone'?`${field('phone','Numéro de téléphone','tel','','autocomplete="tel" placeholder="+33 6 12 34 56 78" required')}<button class="btn primary w-full" type="submit" data-auth="request_code">Recevoir un code →</button>${btn('reset-auth','Changer les identifiants','ghost sm')}`:
  stage==='code'?`<p class="onboard-hint">${E(S.code_delivery||'Vérifiez vos messages Telegram pour obtenir le code.')}</p>${field('code','Code Telegram','text','','autocomplete="one-time-code" required')}<button class="btn primary w-full" type="submit" data-auth="sign_in">Vérifier →</button>${btn('reset-auth','Recommencer','ghost sm')}`:
  `${field('password','Mot de passe 2FA','password','','autocomplete="off" required')}<button class="btn primary w-full" type="submit" data-auth="sign_in">Se connecter →</button>${btn('reset-auth','Recommencer','ghost sm')}`;
  return `<div class="onboarding-layout"><div class="welcome-identity"><div class="onboard-logo">${telegramMark}</div><div class="welcome-kicker">TELEPILOT / LOCAL STUDIO</div><h1>Votre espace<br><em>Telegram.</em></h1><p>Un seul endroit pour votre réseau, vos médias et vos publications.</p><div class="welcome-privacy">${icon('check')} Privé. Hébergé sur votre Mac.</div></div><section class="login-card glass"><div class="login-card-header"><span class="step-label">Connexion · ${E(steps[stage]||'Sécurité')}</span><span class="step-counter">${{credentials:'01',phone:'02',code:'03',password:'04'}[stage]||'01'} / 04</span></div><h2>Connecter Telegram</h2><p>Accédez à votre espace de travail.</p><form id="auth-form" class="form-grid">${body}</form></section><div class="onboard-ambient one" data-parallax="10"></div><div class="onboard-ambient two" data-parallax="-7"></div></div>`;
}
function home(){
  const channels=A(S.channels),admin=channels.filter(c=>['admin','owner'].includes(c.role)).length;
  const media=A(S.media).length,planned=A(S.tasks).filter(t=>t.kind==='publish'&&['scheduled','pending'].includes(t.state)).length;
  const active=A(S.exchanges).filter(e=>['Accord conclu','En cours','Publication programmée'].includes(e.state)).length;
  return `${head('Vue d’ensemble','',btn('sync',icon('refresh')+' Actualiser','sm'))}<section class="welcome-strip glass" data-parallax="3"><div><span class="welcome-label">Bonjour, ${E(S.identity||'')}</span><h2>Votre espace de travail.</h2><p>Tout est prêt pour gérer vos canaux.</p><div class="welcome-actions">${btn('download',icon('download')+' Importer des médias','primary')}${btn('go-studio',icon('plus')+' Nouvelle publication')}</div></div><div class="welcome-art">${telegramMark}</div></section><div class="grid cols-4">${stat('Canaux',admin,'Administrés','network')}${stat('Médias',media,'En bibliothèque','image')}${stat('Programmés',planned,'Publications','calendar')}${stat('Partenariats',active,'Actifs','handshake')}</div><div class="grid cols-2 mt-20"><section class="glass card"><div class="card-top"><div class="card-title">Réseau</div>${btn('sync','Synchroniser','ghost sm')}</div><div class="mini-list">${channels.slice(0,5).map(c=>`<button class="mini-row quick-channel" data-route="network">${avatar(c)}<div class="quick-channel-body"><strong>${E(c.title)}</strong><small>${TYPES[c.entity_type]||'Canal'}</small></div><span class="quiet">›</span></button>`).join('')||empty('Réseau vide','Synchronisez vos canaux.',btn('sync','Synchroniser','sm primary'))}</div></section><section class="glass card"><div class="card-top"><div class="card-title">Activité récente</div>${btn('show-activity','Voir tout','ghost sm')}</div><div class="mini-list">${A(S.events).slice(0,5).map(e=>`<div class="mini-row"><div class="mini-icon">${icon('info')}</div><div><strong>${E(e.title)}</strong><small>${E(e.detail||'')}</small></div><span class="quiet text-sm">${date(e.created_at)}</span></div>`).join('')||empty('Aucune activité','Vos actions apparaîtront ici.')}</div></section></div>`;
}
function filteredChannels(){const q=U.search.toLowerCase(),scope=U.networkFilter;return A(S.channels).filter(c=>{if(q&&!`${c.title||''} ${c.category||''} ${c.notes||''}`.toLowerCase().includes(q))return false;return scope==='all'||scope==='managed'&&['owner','admin'].includes(c.role)||scope==='groups'&&c.entity_type!=='broadcast'||scope==='followed'&&!['owner','admin'].includes(c.role)}).sort((a,b)=>(['owner','admin'].includes(b.role)?1:0)-(['owner','admin'].includes(a.role)?1:0)||String(a.title).localeCompare(String(b.title)))}
function network(){
  const list=filteredChannels();if(U.channel==null&&list.length)U.channel=list[0].id;
  const c=list.find(x=>String(x.id)===String(U.channel));
  return `${head('Mon réseau','',btn('create-community',icon('plus')+' Créer','primary')+btn('sync',icon('refresh')+' Synchroniser','sm'))}${subnav()}<div class="split network-split"><section class="glass panel-list"><div class="toolbar network-toolbar"><div class="search-field w-full">${icon('search')}<input data-live="network-search" placeholder="Rechercher" value="${E(U.search)}"></div></div><div class="pills network-tabs">${[['all','Tous'],['managed','À moi'],['groups','Groupes'],['followed','Suivis']].map(([v,l])=>`<button class="chip ${U.networkFilter===v?'active':''}" data-netfilter="${v}">${l}</button>`).join('')}</div><div class="section-count">${list.length} discussions</div><div class="channel-list scrollable">${list.map(c=>`<button class="channel-item ${String(c.id)===String(U.channel)?'active':''}" data-channel="${c.id}">${avatar(c)}<span class="channel-text"><strong>${E(c.title)}</strong><small>${TYPES[c.entity_type]||'Entité'} · ${ROLES[c.role]||'Membre'}</small></span><span class="channel-count">${c.subscribers!=null?fmt(c.subscribers):''}</span></button>`).join('')||empty('Réseau vide','Synchronisez votre compte pour retrouver vos canaux.',btn('sync','Synchroniser','primary sm'))}</div></section><section class="glass detail-panel">${c?`<div class="profile-hero">${avatar(c,true)}<h2>${E(c.title)}</h2><div class="detail-meta">${E(TYPES[c.entity_type]||'Telegram')} · ${c.visibility==='public'?'Public':'Privé'}</div></div><div class="profile-content"><div class="detail-description">${E(c.description||'')}</div><div class="info-list">${info('Membres',fmt(c.subscribers))}${info('Votre accès',E(ROLES[c.role]||'—'))}${info('Publication',c.can_post?'Disponible':'Lecture seule')}</div></div><div class="detail-actions">${btn('download-channel',icon('download')+' Télécharger les médias','primary',`data-id="${c.id}"`)}<div class="grid cols-2">${btn('recent',icon('eye')+' Publications','',`data-id="${c.id}"`)}${btn('notes',icon('file')+' Notes','',`data-id="${c.id}"`)}</div>${c.username?btn('open-channel',icon('external')+' Ouvrir dans Telegram','ghost',`data-username="${E(c.username)}"`):''}</div>`:empty('Sélectionnez un canal','Ses informations apparaîtront ici.')}</section></div>`;
}
function organisation(){const ch=A(S.channels),links=A(S.network_links),children=links.map(l=>{const a=ch.find(c=>c.id===l.parent_id),b=ch.find(c=>c.id===l.child_id);return a&&b?`<div class="network-graph" style="min-height:100px;padding:12px"><div class="network-node"><strong>${E(a.title)}</strong><small>${E(TYPES[a.entity_type])}</small></div><span class="network-arrow">→</span><div class="network-node"><strong>${E(b.title)}</strong><small>${E(l.label||TYPES[b.entity_type])}</small></div>${btn('unlink-network','Retirer','sm ghost',`data-id="${b.id}"`)}</div>`:''}).join('');return `${head('Architecture du réseau','Organisez visuellement les relations entre vos canaux et groupes.',btn('link-network',icon('plus')+' Associer deux entités','primary'))}${subnav()}<div class="glass card"><div class="card-top"><div><div class="card-title">Votre écosystème Telegram</div><div class="card-sub">Organisation locale : ne modifie pas les liens ou invitations Telegram</div></div>${badge(`${links.length} associations`,'good')}</div>${children||empty('Votre réseau n’est pas encore organisé','Associez un canal principal à un ou plusieurs canaux ou groupes secondaires.',btn('link-network','Créer une association','primary'))}</div><section class="glass card mt-20"><div class="card-title">Entités disponibles</div><div class="pills mt-20">${ch.map(c=>`<span class="chip">${E(c.title)} · ${E(TYPES[c.entity_type]||'—')}</span>`).join('')||'<span class="muted">Synchronisez votre réseau pour commencer.</span>'}</div></section>`}
function sources(){
  const list=A(S.channels).filter(c=>`${c.title||''} ${c.category||''}`.toLowerCase().includes(U.sourceSearch.toLowerCase()));
  return `${head('Depuis mon réseau','Importez directement depuis vos canaux et groupes.',btn('create-community',icon('plus')+' Créer un canal','primary')+btn('sync',icon('refresh')+' Actualiser','sm'))}${subnav()}<div class="toolbar contents-toolbar"><div class="search-field">${icon('search')}<input data-live="source-search" value="${E(U.sourceSearch)}" placeholder="Rechercher un canal…"></div></div><div class="source-gallery">${list.map(c=>`<article class="glass source-card"><div class="source-card-top">${avatar(c,true)}<span class="source-kind">${E(TYPES[c.entity_type]||'Canal')}</span></div><h3>${E(c.title)}</h3><p>${c.subscribers!=null?fmt(c.subscribers)+' membres':'Membres indisponibles'} · ${c.visibility==='public'?'Public':'Privé'}</p><div class="source-card-actions">${btn('download-channel',icon('download')+' Importer','primary sm',`data-id="${c.id}"`)}${btn('recent','Aperçu','sm',`data-id="${c.id}"`)}</div>${c.protected?'<small class="source-warning">Contenu protégé par Telegram</small>':''}</article>`).join('')||empty('Aucun canal','Synchronisez votre réseau pour voir vos sources.',btn('sync','Synchroniser','primary'))}</div>`;
}
function mediaFiltered(){let media=A(S.media);const query=U.mediaSearch.toLowerCase();if(query)media=media.filter(m=>`${m.name||''} ${m.caption||''}`.toLowerCase().includes(query));if(U.mediaFilter==='photo'||U.mediaFilter==='video')media=media.filter(m=>m.kind===U.mediaFilter);if(U.mediaFilter==='favorite')media=media.filter(m=>m.favorite);if(U.mediaFilter==='approved')media=media.filter(m=>m.reviewed&&['own','partner','licensed'].includes(m.rights)&&!m.revoked);return media}
function library(){
  const all=mediaFiltered(),m=all.slice(0,U.mediaLimit);
  const blur=Math.max(0,Math.min(32,U.blurStrength));
  return `${head('Médiathèque','',btn('import-local',icon('plus')+' Importer des fichiers')+btn('download',icon('download')+' Depuis Telegram','primary'))}${subnav()}<div class="library-controls"><div class="search-field">${icon('search')}<input data-live="media-search" value="${E(U.mediaSearch)}" placeholder="Rechercher un média"></div><div class="segmented">${[['all','Tous'],['photo','Photos'],['video','Vidéos'],['approved','Approuvés'],['favorite','Favoris']].map(([v,l])=>`<button class="${U.mediaFilter===v?'active':''}" data-mediafilter="${v}">${l}</button>`).join('')}</div><label class="blur-control" for="blur-slider"><span>${icon('eye')} Flou</span><input type="range" id="blur-slider" min="0" max="32" value="${blur}" aria-label="Intensité du flou"/><output id="blur-value">${blur}px</output></label></div>${U.selectedMedia.size?`<div class="selection-tray"><strong>${U.selectedMedia.size} sélectionné(s)</strong>${btn('compose-selected','Publier','sm primary')}${btn('review-selected','Droits','sm')}${btn('favorite-selected','Favoris','sm')}${btn('open-folder-selected','Ouvrir le dossier','sm')}${btn('withdraw-selected','Retirer','sm danger')}${btn('clear-selected','Annuler','sm ghost')}</div>`:''}${m.length?`<div class="media-grid">${m.map(x=>{const isBlurred=!!(x.sensitive&&S.blur&&!U.revealedMedia.has(x.id));const src='/api/media/'+encodeURIComponent(x.id);return `<div class="media-tile ${U.selectedMedia.has(x.id)?'selected':''}" data-media="${x.id}"><div class="media-art ${isBlurred?'blurred':''}" data-media-img="${x.id}">${x.kind==='video'?`<video muted preload="metadata" playsinline src="${src}#t=0.1" aria-label="Aperçu vidéo"></video>`:`<img loading="lazy" src="${src}" alt="Aperçu du média">`}<span class="media-check">${U.selectedMedia.has(x.id)?'✓':''}</span><span class="media-kind">${x.kind==='video'?'Vidéo':'Photo'}</span>${x.sensitive&&S.blur?`<button type="button" class="reveal-media" data-action="toggle-blur" data-id="${x.id}" title="${isBlurred?'Afficher':'Masquer'}" aria-label="${isBlurred?'Afficher':'Masquer'} le média">${icon(isBlurred?'eye':'eye-off')}</button>`:''}</div><div class="media-meta"><strong>${E(x.name)}</strong><small>${fmt(Math.round((x.size||0)/1024))} Ko · ${E(RIGHTS[x.rights]||'À valider')}</small></div></div>`}).join('')}</div>${all.length>U.mediaLimit?`<div class="center-actions">${btn('more-media','Afficher davantage')}</div>`:''}`:empty('Aucun média','Téléchargez des photos ou vidéos depuis votre réseau.',btn('download','Importer depuis Telegram','primary'))}`;
}
function requestThumbnails(){ /* Media and videos use authenticated local streaming URLs. */ }
function studio(){const approved=mediaOptions(),selected=U.composeMedia;return `${head('Studio de publication','Préparez vos messages et programmez-les sur vos canaux.',btn('go-queue',icon('clock')+' Voir la file'))}${subnav()}<div class="split"><section class="glass card"><div class="card-top"><div><div class="card-title">Nouvelle publication</div><div class="card-sub">Texte, médias et destination</div></div>${badge('Éditeur','good')}</div><form id="studio-form" class="form-grid">${field('channel_id','Canal de destination','select',channelOptions(true))}${field('text','Votre message','textarea',U.draft.text||'','rows="7" placeholder="Rédigez votre publication…"')}${field('credit','Crédit / source (facultatif)','text',U.draft.credit||'','placeholder="Auteur ou canal à créditer"')}<div class="form-row">${field('due_at','Date et heure de publication','datetime-local',U.draft.due_at||localDate(3600))}<div class="field"><label>Options</label><label class="check-row" style="margin-top:10px"><input type="checkbox" name="allow_repeat"> Autoriser une republication déjà utilisée</label></div></div><div class="flex gap-8" style="flex-wrap:wrap"><button class="btn" type="submit" data-mode="draft">Enregistrer un brouillon</button><button class="btn" type="submit" data-mode="scheduled">Programmer</button><button class="btn primary" type="submit" data-mode="now">${icon('send')} Publier maintenant</button></div></form></section><section class="glass card"><div class="card-top"><div><div class="card-title">Médias approuvés</div><div class="card-sub">Sélectionnez jusqu’à 10 médias</div></div>${badge(`${selected.size} sélectionné(s)`)}</div><div class="scrollable" style="max-height:520px;overflow:auto">${approved.map(([id,title])=>`<label class="mini-row" style="cursor:pointer"><div class="flex align-center gap-12"><input type="checkbox" data-composemedia="${id}" ${selected.has(Number(id))?'checked':''}><div class="mini-icon">${icon('image')}</div><div><strong>${E(title)}</strong><small>Disponible pour une publication</small></div></div></label>`).join('')||empty('Aucun média approuvé','Vous pouvez publier du texte ou approuver des médias depuis la médiathèque.',btn('show-library','Ouvrir la médiathèque','sm'))}</div></section></div>`}
function queue(){const tasks=A(S.tasks);return `${head('File & historique','Suivez vos publications et téléchargements en temps réel.',btn('toggle-engine',S.engine?icon('pause')+' Suspendre les publications':icon('send')+' Activer les publications',S.engine?'':'primary'))}${subnav()}<div class="tip" style="margin-bottom:17px"><strong>${S.engine?'Publications actives':'Publications suspendues'}.</strong> Les imports se lancent indépendamment de la file. Les publications validées nécessitent une activation explicite.</div><div class="glass card">${table(['TÂCHE','TYPE','ÉTAT','ÉCHÉANCE','PROGRESSION / ACTIONS'],tasks.slice(0,140).map(t=>{let p={};try{p=JSON.parse(t.payload)}catch{}return row([`<span class="table-main">${E(t.title)}</span><div class="quiet text-sm">${E(t.id).slice(0,10)}</div>`,t.kind==='import'?'Importation':'Publication',badge(STATES[t.state]||t.state,t.state==='completed'?'good':t.state==='failed'?'bad':t.state==='unknown'?'warn':''),date(t.due_at),`<div class="table-actions">${t.kind==='import'?`${fmt(p.downloaded||0)} fichiers <button data-action="pause-task" data-id="${E(t.id)}">${t.paused?'Reprendre':'Pause'}</button>`:''}${!['completed','cancelled'].includes(t.state)?`<button data-action="cancel-task" data-id="${E(t.id)}">Annuler</button>`:''}${t.state==='unknown'?`<button data-action="resolve-task" data-id="${E(t.id)}">Vérifier</button>`:''}</div>`])}))}</div>`}
function calendar(){const d=new Date(),days=new Date(d.getFullYear(),d.getMonth()+1,0).getDate(),offset=(new Date(d.getFullYear(),d.getMonth(),1).getDay()+6)%7,all=[...A(S.tasks),...A(S.exchanges)];return `${head('Calendrier','Visualisez vos prochaines publications et opérations.')}${subnav()}<div class="calendar-layout"><section class="glass card"><div class="card-top"><div><div class="card-title">${d.toLocaleDateString('fr-FR',{month:'long',year:'numeric'})}</div><div class="card-sub">Publications et échanges prévus</div></div></div><div class="cal-grid">${['L','M','M','J','V','S','D'].map(x=>`<div class="quiet" style="text-align:center;font-size:10px;padding:8px">${x}</div>`).join('')}${Array.from({length:offset},()=>'<div></div>').join('')}${Array.from({length:days},(_,i)=>{const day=i+1,has=all.some(t=>{const z=new Date(t.due_at*1000);return z.getFullYear()===d.getFullYear()&&z.getMonth()===d.getMonth()&&z.getDate()===day});return `<div class="cal-day ${has?'has':''}">${day}</div>`}).join('')}</div></section><section class="glass card"><div class="card-title" style="margin-bottom:22px">À venir</div><div class="mini-list">${all.filter(t=>t.due_at>=Date.now()/1000).sort((a,b)=>a.due_at-b.due_at).slice(0,16).map(t=>`<div class="mini-row"><div class="flex gap-12 align-center"><div class="mini-icon">${icon('calendar')}</div><div><strong>${E(t.title)}</strong><small>${E(STATES[t.state]||t.state)}</small></div></div><span class="quiet text-sm">${date(t.due_at)}</span></div>`).join('')||empty('Calendrier libre','Les publications programmées apparaîtront ici.')}</div></section></div>`}
function rules(){return `${head('Automatisations','Configurez vos règles de fonctionnement et de surveillance.')}${subnav()}<div class="grid cols-2"><section class="glass card"><div class="card-title">Règles de publication</div><p class="subtitle">Définissez un espacement minimal entre les envois.</p><form id="rules-form" class="form-grid mt-20">${field('send_interval','Intervalle minimum en secondes','number',S.interval,'min="60" max="86400"')}<label class="check-row"><input name="auto_watch" type="checkbox" ${S.auto_watch?'checked':''}> Surveiller périodiquement les sources activées</label><button type="submit" class="btn primary">Enregistrer les règles</button></form></section><section class="glass card"><div class="card-title">Importation automatique</div><p class="subtitle">Activez-la individuellement pour chaque source autorisée.</p><div class="mini-list mt-20">${A(S.sources).map(src=>`<div class="mini-row"><div><strong>${E(src.title)}</strong><small>${src.auto_import?'Synchronisation active':'Importation désactivée'}</small></div>${btn('auto-source',src.auto_import?'Désactiver':'Activer','sm',`data-id="${src.id}" data-status="${src.auto_import?'1':'0'}"`)}</div>`).join('')||empty('Aucune source','Ajoutez d’abord un canal source.',btn('show-sources','Sources','sm'))}</div></section></div>`}
function partners(){
  const ps=A(S.partners);if(U.selectedPartner==null&&ps.length)U.selectedPartner=ps[0].id;
  const current=ps.find(p=>String(p.id)===String(U.selectedPartner));
  const msgs=U.partnerMessages;
  return `${head('Partenaires','Vos conversations et collaborations.',btn('add-partner',icon('plus')+' Ajouter un partenaire','primary'))}${subnav()}<div class="split partner-split"><section class="glass partner-list"><div class="partner-list-title">Conversations <span>${ps.length}</span></div>${ps.map(p=>`<button class="partner-row ${String(p.id)===String(U.selectedPartner)?'active':''}" data-partner="${p.id}"><span class="partner-avatar">${E((p.name||'?')[0].toUpperCase())}</span><span class="channel-text"><strong>${E(p.name)}</strong><small>${E(p.handle||'Aucun identifiant')}</small></span><span class="partner-next">›</span></button>`).join('')||empty('Aucun partenaire','Ajoutez un partenaire pour retrouver vos conversations.',btn('add-partner','Ajouter','sm primary'))}</section><section class="glass conversation-panel">${current?`<div class="conversation-header"><span class="partner-avatar">${E((current.name||'?')[0].toUpperCase())}</span><div><strong>${E(current.name)}</strong><small>${E(current.handle||'Identifiant manquant')}</small></div>${btn('load-partner-messages',icon('refresh'),'sm ghost',`data-id="${current.id}"`)}${btn('partner-details',icon('info'),'sm ghost',`data-id="${current.id}"`)}</div><div class="conversation-messages">${U.partnerError?`<div class="conversation-note">${E(U.partnerError)}</div>`:msgs.length?msgs.map(msg=>`<div class="bubble-row ${msg.out?'sent':'received'}"><div class="message-bubble"><div>${E(msg.text||'Pièce jointe')}</div><small>${date(msg.date)}</small></div></div>`).join(''):`<div class="conversation-placeholder">${icon('message')}<h3>Vos échanges Telegram</h3><p>Ouvrez la conversation pour afficher les messages existants.</p>${btn('load-partner-messages','Afficher la discussion','primary sm',`data-id="${current.id}"`)}</div>`}</div><form id="partner-reply-form" class="conversation-compose"><input type="hidden" name="partner_id" value="${current.id}"><input name="message" class="input" placeholder="Écrire une réponse…" autocomplete="off" maxlength="4096" required aria-label="Répondre au partenaire"><button class="send-button" type="submit" aria-label="Envoyer">${icon('send')}</button></form>`:empty('Sélectionnez un partenaire','Choisissez un contact dans la liste.')}</section></div>`;
}
function exchanges(){return `${head('Échanges publicitaires','Préparez et suivez vos collaborations de visibilité.',btn('add-exchange',icon('plus')+' Préparer un échange','primary'))}${subnav()}<div class="grid cols-3" style="margin-bottom:19px">${stat('Propositions',A(S.exchanges).length,'Toutes les demandes','handshake')}${stat('Accords conclus',A(S.exchanges).filter(x=>x.state==='Accord conclu').length,'Prêts à programmer','check','#a4b4ff')}${stat('Échanges terminés',A(S.exchanges).filter(x=>x.state==='Échange terminé').length,'Historique','chart','#e1b785')}</div><section class="glass card">${table(['ÉCHANGE','ÉTAT','DATE','DURÉE','ACTIONS'],A(S.exchanges).map(x=>row([`<span class="table-main">${E(x.title)}</span>`,badge(x.state,x.state==='Accord conclu'?'good':''),date(x.due_at),`${fmt(x.duration_hours)} h`,`<div class="table-actions"><button data-action="exchange-details" data-id="${x.id}">Voir</button><button data-action="exchange-state" data-id="${x.id}">État</button><button data-action="exchange-schedule" data-id="${x.id}">Programmer</button><button data-action="exchange-verify" data-id="${x.id}">Vérifier</button></div>`])))}</section>`}
function assistant(){return `${head('Assistant de rédaction','Préparez vos propositions et réponses avant envoi.')}${subnav()}<div class="tip" style="margin-bottom:20px"><strong>Modèles locaux.</strong> Cette fonction ne contacte aucune IA externe et n’envoie aucun message automatiquement.</div><div class="split"><section class="glass card"><form id="assistant-form" class="form-grid">${field('partner','Nom du partenaire')}${field('intent','Objectif','select',options([['Proposer','Proposer un échange'],['Négocier','Négocier une offre'],['Refuser','Refuser poliment']]))}${field('date','Date envisagée')}${field('terms','Conditions et détails','textarea','','rows="5"')}<button type="submit" class="btn primary">${icon('spark')} Préparer le texte</button></form></section><section class="glass card"><div class="card-title" style="margin-bottom:18px">Proposition</div><textarea class="textarea" id="assistant-output" style="min-height:350px" placeholder="Votre message apparaîtra ici après génération…"></textarea><div class="mt-14">${btn('copy-assistant','Copier le texte','primary')}</div></section></div>`}
function statistics(){const obs=A(S.observations),views=obs.reduce((acc,o)=>acc+(o.views||0),0),reactions=obs.reduce((acc,o)=>acc+(o.reactions||0),0),shares=obs.reduce((acc,o)=>acc+(o.forwards||0),0);const nums=obs.filter(o=>o.views!=null).slice(0,16).reverse(),highest=Math.max(1,...nums.map(o=>o.views||0));return `${head('Statistiques','Des données observées, jamais des chiffres inventés.',btn('sync',icon('refresh')+' Actualiser','sm'))}${subnav()}<div class="grid cols-4">${stat('Publications observées',obs.length,'Historique accessible','chart')}${stat('Vues observées',views,'Somme des observations','eye','#91a9ff')}${stat('Réactions',reactions,'Réactions disponibles','heart','#bc9cff')}${stat('Partages',shares,'Transferts observés','send','#f1c687')}</div><section class="glass card mt-20"><div class="card-top"><div><div class="card-title">Vues des publications suivies</div><div class="card-sub">Jusqu’à 16 observations disponibles</div></div>${badge('Données Telegram','good')}</div><div style="min-height:240px;display:flex;align-items:end;gap:10px;border-bottom:1px solid var(--stroke);padding:10px 4px 0">${nums.length?nums.map(o=>`<div title="${fmt(o.views)} vues" style="height:${Math.max(5,(o.views||0)/highest*95)}%;min-height:8px;flex:1;background:linear-gradient(180deg,#81ebce,#5d83c5);border-radius:7px 7px 0 0;opacity:.85"></div>`).join(''):empty('Aucune observation','Activez la surveillance des sources pour alimenter ce graphique.')}</div></section><section class="glass card mt-20">${table(['PUBLICATION','VUES','RÉACTIONS','PARTAGES','OBSERVÉ LE'],obs.slice(0,60).map(x=>row([E((x.text||'Média').slice(0,80)),fmt(x.views),fmt(x.reactions),fmt(x.forwards),date(x.observed_at)])))}</section>`}
function watch(){return `${head('Surveillance','Suivez les événements des sources configurées.',btn('watch',icon('refresh')+' Observer maintenant','primary'))}${subnav()}<div class="tip" style="margin-bottom:19px">Surveillance des sources accessibles et autorisées, dans les limites de l’API Telegram. Aucune republication automatique n’est déclenchée par une observation.</div><div class="glass card">${table(['ÉVÉNEMENT','DÉTAIL','DATE'],A(S.events).filter(e=>e.kind==='watch'||e.kind==='sync'||e.kind==='error').slice(0,90).map(e=>row([`<span class="table-main">${E(e.title)}</span>`,E(e.detail||'—'),date(e.created_at)])))}</div>`}
function activity(){return `${head('Journal d’activité','Tout ce qui s’est passé dans votre espace.')}${subnav()}<section class="glass card">${table(['ÉVÉNEMENT','DÉTAIL','CANAL','DATE'],A(S.events).slice(0,100).map(e=>row([`<span class="table-main">${E(e.title)}</span>`,E(e.detail||'—'),e.channel_id?E(e.channel_id):'—',date(e.created_at)])))}</section>`}
function settings(){const stage=S.connected?'connected':S.auth_state||'credentials';return `${head('Compte & préférences','Votre connexion Telegram et vos réglages locaux.') }<div class="split"><section class="glass card"><div class="card-top"><div><div class="card-title">Connexion Telegram</div><div class="card-sub">Authentification progressive et sécurisée</div></div>${badge(S.connected?'Connecté':'À configurer',S.connected?'good':'warn')}</div>${stage==='connected'?`<div class="flex align-center gap-16"><div class="avatar">${E((S.identity||'T')[0])}</div><div><strong>${E(S.identity)}</strong><div class="muted text-sm">Session Telegram active</div></div></div><div class="flex gap-8 mt-28">${btn('sync','Synchroniser les canaux','primary')}${btn('logout','Déconnecter la session','danger')}</div>`:`<form class="form-grid" id="auth-form">${stage==='credentials'?`<div class="tip">Étape 1 sur 4 · Récupérez l’API ID et l’API hash sur <strong>my.telegram.org</strong>.</div>${field('api_id','API ID','text',S.api_id||'','autocomplete="off" placeholder="Identifiant numérique"')}${field('api_hash','API Hash','password','','autocomplete="off" placeholder="Clé Telegram"')}<label class="check-row"><input type="checkbox" name="remember" checked> Enregistrer l’API hash dans le trousseau macOS</label><button class="btn primary" type="submit" data-auth="configure">Continuer</button>${btn('telegram-api','Obtenir mes identifiants','sm')}`:stage==='phone'?`<div class="tip">Étape 2 · Saisissez votre numéro au format international.</div>${field('phone','Numéro de téléphone','tel','','placeholder="+33612345678"')}<button class="btn primary" type="submit" data-auth="request_code">Recevoir mon code</button>${btn('reset-auth','Changer l’API','sm ghost')}`:stage==='code'?`<div class="tip">Étape 3 · ${E(S.code_delivery||'Consultez le code reçu dans Telegram.')}</div>${field('code','Code de vérification','text','','autocomplete="off"')}<button class="btn primary" type="submit" data-auth="sign_in">Vérifier le code</button>${btn('reset-auth','Recommencer','sm ghost')}`:`<div class="tip">Étape 4 · Mot de passe de vérification en deux étapes.</div>${field('password','Mot de passe 2FA','password','','autocomplete="off"')}<button class="btn primary" type="submit" data-auth="sign_in">Terminer la connexion</button>${btn('reset-auth','Recommencer','sm ghost')}`}</form>`}</section><section class="glass card"><div class="card-title">Préférences & confidentialité</div><p class="subtitle">Les codes et mots de passe ne sont pas conservés dans l’interface.</p><form class="form-grid mt-20" id="preferences-form"><label class="check-row"><input name="blur" type="checkbox" ${S.blur?'checked':''}> Masquer les aperçus sensibles</label><button class="btn" type="submit">Enregistrer les préférences</button></form><hr class="divider"><div class="card-title">Stockage local</div><p class="muted text-sm" style="overflow-wrap:anywhere">${E(S.root||'—')}</p><div class="flex gap-8" style="flex-wrap:wrap">${btn('backup',icon('file')+' Sauvegarder SQLite','sm')}${btn('open-logs','Ouvrir les logs','sm')}</div><div class="tip mt-20">Aucune ressource externe n’est chargée par cette interface. Les fichiers et sessions restent dans le dossier local TelePilot.</div></section></div>`}
function localDate(delta=0){let d=new Date(Date.now()+delta*1000);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}T${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}`}
function showModal(title,body,form='',wide=false,subtitle=''){const box=document.getElementById('modal'),veil=document.getElementById('modal-backdrop');U.activeModal={title,form};box.className='modal'+(wide?' wide':'');box.innerHTML=`<div class="modal-header"><div><div class="eyebrow">TELEPILOT</div><h2>${E(title)}</h2>${subtitle?`<p>${E(subtitle)}</p>`:''}</div><button class="modal-close" data-action="close-modal" aria-label="Fermer">×</button></div>${form?`<form class="form-grid" id="${E(form)}">${body}<div class="modal-footer"><button type="button" class="btn" data-action="close-modal">Annuler</button><button type="submit" class="btn primary">Valider</button></div></form>`:body}`;veil.classList.remove('hidden')}
function closeModal(){document.getElementById('modal-backdrop').classList.add('hidden');U.activeModal=null;render()}
function formValues(form){const args={};for(const el of form.elements){if(!el.name)continue;args[el.name]=el.type==='checkbox'?!!el.checked:el.type==='number'?Number(el.value):el.value}return args}
function selectMedia(c=null){const channels=A(S.channels),chosen=c??U.importChannel??channels[0]?.id;if(!channels.length){toast('Connectez Telegram et synchronisez le réseau.',true);navigate('settings');return}U.importChannel=chosen;const body=`${field('channel_id','Canal ou groupe','select',channelOptions(false,chosen))}${field('kind','Type de médias','select',options([['all','Photos et vidéos'],['photo','Photos uniquement'],['video','Vidéos uniquement']],U.importKind))}<div class="tip"><strong>Deux possibilités :</strong> récupérer tous les médias accessibles, ou choisir les publications à enregistrer. Le téléchargement respecte les protections Telegram.</div><div class="grid cols-2"><button type="button" class="btn" data-action="download-pick">${icon('image')} Choisir les médias</button><button type="button" class="btn primary" data-action="download-all">${icon('download')} Tout télécharger</button></div><details style="color:#91a8bc;font-size:12px"><summary style="cursor:pointer">Options avancées</summary><div class="form-row mt-14">${field('maximum','Messages à parcourir (0 = tous)','number',0,'min="0" max="100000"')}</div></details>`;showModal('Télécharger les médias',`<form id="download-form" class="form-grid">${body}</form>`,'',false,'Choisissez un canal et lancez l’importation.')}
function downloadOptions(){const form=document.getElementById('download-form');if(!form)return null;const v=formValues(form);return {channel_id:Number(v.channel_id),kind:v.kind,photos:v.kind!=='video',videos:v.kind!=='photo',permission_declared:true,maximum:Number(v.maximum)>0?Number(v.maximum):null}}
function startDownload(all){const d=downloadOptions();if(!d)return;U.importChannel=d.channel_id;U.importKind=d.kind;closeModal();if(all){const {kind,...args}=d;run('import_channel_media',args)}else{U.pendingBrowse=d;toast('Recherche des médias du canal…');run('browse_channel_media',{channel_id:d.channel_id,kind:d.kind,limit:200,permission_declared:true})}}
function showPicker(result){const opts=U.pendingBrowse;if(!opts||result.channel_id!==opts.channel_id)return;const messages=A(result.messages);U.previewMessageIds=new Set();if(!messages.length){toast('Aucun média dans les 200 dernières publications. Essayez « Tout télécharger ».',true);return}const content=`<div class="tip">Aperçu des 200 dernières publications. Sélectionnez les photos ou vidéos à télécharger, puis confirmez.</div><div class="scrollable" style="max-height:420px;overflow:auto;margin-top:15px">${messages.map(m=>`<label class="mini-row"><div class="flex align-center gap-12"><input type="checkbox" data-preview="${m.id}"><div class="mini-icon">${m.kind==='photo'?icon('image'):icon('eye')}</div><div><strong>${m.kind==='photo'?'Photo':'Vidéo'} #${m.id}</strong><small>${E(String(m.text||'Sans légende').slice(0,160))} · ${date(m.date)}</small></div></div></label>`).join('')}</div><div class="modal-footer">${btn('preview-all','Tout sélectionner','sm')}${btn('download-selection',icon('download')+' Télécharger la sélection','primary')}</div>`;showModal('Choisir les médias',content,'',true)}
function showRecent(data){const messages=A(data);showModal('Dernières publications',`<div class="scrollable" style="max-height:480px;overflow:auto">${messages.map(m=>`<div class="mini-row"><div><strong>#${m.id} · ${E(m.kind||'Message')}</strong><small>${E(String(m.text||'Sans texte').slice(0,550))}</small></div><span class="quiet">${date(m.date)}</span></div>`).join('')||empty('Aucune publication','Telegram n’a retourné aucun message accessible.')}</div>`)}
function mediaReview(){const id=[...U.selectedMedia][0];if(!id)return;const m=A(S.media).find(x=>x.id===id);if(!m)return;showModal('Valider un média',`${field('rights','Droits de diffusion','select',options(Object.entries(RIGHTS).map(([v,l])=>[v,l]),m.rights))}${field('evidence','Référence de l’autorisation','textarea',m.evidence||'','rows="3"')}${field('caption','Légende','textarea',m.caption||'','rows="3"')}<label class="check-row"><input type="checkbox" name="reviewed" ${m.reviewed?'checked':''}> Vérification humaine des droits et consentements effectuée</label><label class="check-row"><input type="checkbox" name="sensitive" ${m.sensitive?'checked':''}> Masquer l’aperçu sensible</label><input type="hidden" name="media_id" value="${m.id}">`,'review-form')}
function editNotes(id){const c=A(S.channels).find(x=>String(x.id)===String(id));if(!c)return;showModal('Fiche du canal',`<div class="tip">${E(c.title)} · ${E(TYPES[c.entity_type]||'Canal')} · ${E(ROLES[c.role]||'—')}</div>${field('category','Catégorie','text',c.category||'')}${field('notes','Notes internes','textarea',c.notes||'','rows="6"')}<input type="hidden" name="channel_id" value="${c.id}">`,'notes-form')}
function addSource(){showModal('Ajouter un canal public',`${field('handle','Identifiant ou lien Telegram','text','','placeholder="@nom ou https://t.me/nom"')}<div class="tip">Cette recherche accepte les identifiants publics. Les liens privés nécessitent un accès direct dans Telegram.</div>`,'source-form')}
function linkNetwork(){const ch=A(S.channels);if(ch.length<2){toast('Synchronisez au moins deux canaux ou groupes.',true);return}showModal('Associer deux entités',`${field('parent_id','Canal principal','select',channelOptions())}${field('child_id','Canal rattaché','select',options(ch.map(c=>[c.id,c.title]),ch[1].id))}${field('label','Rôle ou description (facultatif)')}`,'network-form')}
function partnerForm(){showModal('Nouveau partenaire',`${field('name','Nom du partenaire')}${field('handle','Identifiant Telegram','text','','placeholder="@nom"')}${field('channel_id','Canal partenaire','select',options([['','Non associé'],...A(S.channels).map(c=>[c.id,c.title])]))}<div class="form-row">${field('category','Catégorie')}${field('audience','Audience déclarée (facultatif)','number',0,'min="0"')}</div>${field('terms','Conditions','textarea','','rows="3"')}${field('notes','Notes et consentement','textarea','','rows="3"')}<label class="check-row"><input type="checkbox" name="consent"> Consentement enregistré aux propositions automatisées</label>`,'partner-form')}
function exchangeForm(){if(!S.partners?.length){toast('Ajoutez d’abord un partenaire.',true);navigate('partners');return}showModal('Préparer un échange',`${field('title','Nom de l’échange')}${field('partner_id','Partenaire','select',options(A(S.partners).map(p=>[p.id,p.name])))}${field('channel_id','Votre canal de diffusion','select',channelOptions(true))}${field('own_copy','Texte à publier sur votre canal','textarea','','rows="3"')}${field('partner_copy','Texte attendu chez votre partenaire','textarea','','rows="3"')}<div class="form-row">${field('due_at','Date prévue','datetime-local',localDate(3600))}${field('duration_hours','Durée (heures)','number',24,'min="1" max="8760"')}</div>${field('expected_link','Lien attendu (facultatif)')}${field('terms','Conditions','textarea','','rows="3"')}`,'exchange-form',true)}
function detailExchange(id){const x=A(S.exchanges).find(x=>String(x.id)===String(id));if(!x)return;showModal(x.title,`<div class="info-list">${info('État',badge(x.state))}${info('Date',date(x.due_at))}${info('Durée',`${fmt(x.duration_hours)} h`)}</div><hr class="divider"><div class="card-title">À publier chez vous</div><p class="subtitle">${E(x.own_copy)}</p><div class="card-title mt-20">À publier chez le partenaire</div><p class="subtitle">${E(x.partner_copy)}</p><div class="card-title mt-20">Conditions</div><p class="subtitle">${E(x.terms||'Aucune')}</p>`)}
function editExchangeState(id){const x=A(S.exchanges).find(x=>String(x.id)===String(id));if(!x)return;const states=['Nouveau','Contact établi','Proposition reçue','Proposition envoyée','Négociation','En attente de validation','Accord conclu','Publication programmée','En cours','Échange terminé','Refusé','Annulé','Litige'];showModal('Modifier le statut',`${field('state','État de l’échange','select',options(states.map(s=>[s,s]),x.state))}<input type="hidden" name="exchange_id" value="${x.id}">`,'state-form')}
function confirmAction(message,action){showModal('Confirmation nécessaire',`<p class="subtitle">${E(message)}</p><div class="modal-footer">${btn('close-modal','Annuler')}${btn('confirm-pending','Confirmer','primary')}</div>`);U.pendingAction=action}
function help(){const details={home:['Vue d’ensemble','Cette page rassemble les informations importantes et les raccourcis vers les principales actions.'],network:['Mon réseau','Sélectionnez un canal à gauche. Sa fiche et ses actions apparaissent à droite. Synchroniser actualise les droits et les canaux.'],organisation:['Organisation','Associez localement un canal principal à des canaux ou groupes secondaires. Aucun lien Telegram n’est modifié.'],sources:['Découverte & sources','Ajoutez un identifiant public puis téléchargez les médias accessibles. Les restrictions Telegram restent applicables.'],library:['Médiathèque','Les photos et vidéos importées sont conservées localement. Cliquez sur une vignette pour sélectionner un média, puis approuvez-le avant publication.'],studio:['Studio','Sélectionnez un canal, rédigez, choisissez des médias approuvés et enregistrez un brouillon ou une publication.'],queue:['File & historique','Les téléchargements sont indépendants de l’activation de la file de publications. Les envois nécessitent votre validation.'],calendar:['Calendrier','Visualisez les envois et échanges programmés.'],rules:['Automatisations','Configurez les intervalles et activez le suivi pour chaque source.'],partners:['Partenaires','Enregistrez les administrateurs avec qui vous collaborez et leurs accords.'],exchanges:['Échanges publicitaires','Préparez les conditions, obtenez l’accord, programmez et vérifiez les échanges consentis.'],assistant:['Rédaction','Ce module utilise des modèles locaux ; il ne contacte aucune IA externe.'],statistics:['Statistiques','Seules les données accessibles et observées sont affichées.'],watch:['Surveillance','Déclenchez le suivi des sources activées.'],activity:['Activité','Consultez l’historique des opérations.'],settings:['Paramètres','Connectez Telegram en plusieurs étapes et gérez le stockage local.']};const [title,desc]=details[U.route]||details.home;showModal('Aide · '+title,`<div class="tip">${E(desc)}</div><div class="mini-row"><div><strong>Une fonction n’est pas disponible ?</strong><small>Consultez le journal local dans Paramètres et vérifiez l’accès Telegram.</small></div></div>`)}
document.addEventListener('click',event=>{
 const route=event.target.closest('[data-route]');if(route){navigate(route.dataset.route);return}
 const chan=event.target.closest('[data-channel]');if(chan){U.channel=Number(chan.dataset.channel);render();return}
 const nf=event.target.closest('[data-netfilter]');if(nf){U.networkFilter=nf.dataset.netfilter;render();return}
 const mf=event.target.closest('[data-mediafilter]');if(mf){U.mediaFilter=mf.dataset.mediafilter;render();return}
 const partner=event.target.closest('[data-partner]');if(partner){U.selectedPartner=Number(partner.dataset.partner);U.partnerMessages=[];U.partnerError='';render();run('partner_messages',{partner_id:U.selectedPartner});return}
 const reveal=event.target.closest('[data-action=toggle-blur]');if(reveal){const id=Number(reveal.dataset.id);U.revealedMedia.has(id)?U.revealedMedia.delete(id):U.revealedMedia.add(id);render();return}
 const tile=event.target.closest('[data-media]');if(tile){const id=Number(tile.dataset.media);U.selectedMedia.has(id)?U.selectedMedia.delete(id):U.selectedMedia.add(id);render();return}
 const act=event.target.closest('[data-action]');if(!act)return;
 const {action,id,username,status}=act.dataset;const ident=id?(/^\d+$/.test(id)?Number(id):id):null;
 switch(action){
 case'close-modal':closeModal();break;
 case'create-community':showModal('Créer dans Telegram',`${field('title','Nom du canal ou groupe','text','','maxlength=128 required')}${field('kind','Type','select',options([['channel','Canal'],['group','Supergroupe']]))}${field('about','Description (facultative)','textarea','','rows=3 maxlength=255')}<p class="quiet text-sm">Création privée par défaut. Vous pourrez définir sa visibilité dans Telegram.</p>`,'community-form');break;
 case'load-partner-messages':U.selectedPartner=ident;U.partnerError='';run('partner_messages',{partner_id:ident});break;
 case'sync':run('sync_channels');break;
 case'go-settings':navigate('settings');break;
 case'go-studio':navigate('studio');break;
 case'go-queue':navigate('queue');break;
 case'go-library':case'show-library':navigate('library');break;
 case'show-sources':navigate('sources');break;
 case'show-activity':navigate('activity');break;
 case'download':selectMedia();break;
 case'download-channel':case'download-source':selectMedia(ident);break;
 case'download-all':startDownload(true);break;
 case'download-pick':startDownload(false);break;
 case'download-selection':{const ids=[...U.previewMessageIds];if(!ids.length){toast('Sélectionnez au moins un média.',true);return}const {kind,...args}=U.pendingBrowse;closeModal();run('import_channel_media',{...args,selected_ids:ids});break}
 case'preview-all':{const els=[...document.querySelectorAll('[data-preview]')];const all=els.every(el=>el.checked);U.previewMessageIds=new Set();for(const el of els){el.checked=!all;if(!all)U.previewMessageIds.add(Number(el.dataset.preview))}break}
 case'import-local':importLocalFiles();break;
 case'more-media':U.mediaLimit+=60;render();break;
 case'clear-selected':U.selectedMedia.clear();render();break;
 case'favorite-selected':for(const id of U.selectedMedia)run('favorite',{media_id:id});U.selectedMedia.clear();break;
 case'review-selected':mediaReview();break;
 case'open-folder-selected':{const item=[...U.selectedMedia][0];if(item)run('open_media_folder',{media_id:item});break}
 case'withdraw-selected':{const ids=[...U.selectedMedia];if(!ids.length)return;confirmAction('Retirer les médias sélectionnés de TelePilot ? Les publications à venir associées seront annulées. Les copies distantes ne sont pas supprimées.',()=>{for(const mid of ids)run('withdraw',{media_id:mid,delete_file:false});U.selectedMedia.clear()});break}

 case'compose-selected':{const selected=[...U.selectedMedia],allowed=A(S.media).filter(m=>selected.includes(m.id)&&m.reviewed&&!m.revoked&&['own','partner','licensed'].includes(m.rights));if(allowed.length!==selected.length){toast('Approuvez les médias avant de les publier.',true);mediaReview();return}U.composeMedia=new Set(selected);navigate('studio');break}
 case'recent':run('recent',{channel_id:ident});break;
 case'notes':editNotes(ident);break;
 case'open-channel':run('external_link',{url:'https://t.me/'+username});break;
 case'discover':addSource();break;
 case'link-network':linkNetwork();break;
 case'unlink-network':confirmAction('Retirer cette association locale ? Les canaux Telegram ne seront pas modifiés.',()=>run('network_unlink',{child_id:ident}));break;
 case'verify-source':run('verify_source',{source_id:ident});break;
 case'auto-source':run('auto_import',{source_id:ident,enabled:status!=='1'});break;
 case'toggle-engine':{if(!S.connected){navigate('settings');toast('Connectez Telegram pour activer les publications.',true);return}if(S.engine){run('engine',{enabled:false})}else{confirmAction('Les publications validées et arrivées à échéance seront réellement envoyées sur Telegram lorsque la file est active. Confirmer ?',()=>run('engine',{enabled:true}))}break}
 case'pause-import':case'pause-task':run('pause',{task_id:id});break;
 case'cancel-import':case'cancel-task':confirmAction('Arrêter cette tâche ? Les médias déjà importés restent dans votre médiathèque.',()=>run('cancel',{task_id:id}));break;
 case'resolve-task':{showModal('Vérifier une publication incertaine',`${field('message_ids','IDs des messages réellement publiés (séparés par des virgules)')}<input type="hidden" name="task_id" value="${E(id)}"><div class="tip">Examinez le canal dans Telegram avant de confirmer. Ne relancez pas aveuglément une publication incertaine.</div>`,'resolve-form');break}
 case'add-partner':partnerForm();break;
 case'partner-details':{const p=A(S.partners).find(p=>p.id===ident);if(p)showModal(p.name,`<div class="info-list">${info('Contact',E(p.handle||'—'))}${info('Catégorie',E(p.category||'—'))}${info('Audience',fmt(p.audience))}${info('Consentement',p.consent?'Oui':'Non')}</div><hr class="divider"><strong>Conditions</strong><p class="subtitle">${E(p.terms||'—')}</p><strong>Notes</strong><p class="subtitle">${E(p.notes||'—')}</p>`);break}
 case'partner-optout':confirmAction('Enregistrer le retrait du consentement de ce partenaire ?',()=>run('partner_optout',{partner_id:ident}));break;
 case'add-exchange':exchangeForm();break;
 case'exchange-details':detailExchange(ident);break;
 case'exchange-state':editExchangeState(ident);break;
 case'exchange-schedule':confirmAction('Programmer votre annonce pour cet échange ? Un accord conclu est nécessaire.',()=>run('exchange_schedule',{exchange_id:ident}));break;
 case'exchange-verify':run('exchange_verify',{exchange_id:ident});break;
 case'watch':run('watch');break;
 case'copy-assistant':{const text=document.getElementById('assistant-output')?.value||'';if(!text){toast('Aucun texte à copier.',true);return}navigator.clipboard?.writeText(text).then(()=>toast('Texte copié.')).catch(()=>toast('Utilisez Cmd+C pour copier ce texte.'));break}
 case'reset-auth':run('reset_auth');break;
 case'telegram-api':run('external_link',{url:'https://my.telegram.org'});break;
 case'logout':confirmAction('Révoquer la session Telegram ? Les publications seront suspendues.',()=>run('logout'));break;
 case'backup':run('backup');break;
 case'open-logs':run('open_logs');break;
 case'confirm-pending':{const fn=U.pendingAction;U.pendingAction=null;closeModal();if(fn)fn();break}
 default:break;
 }
});
document.addEventListener('error',event=>{if(event.target.matches('img.channel-avatar-img'))event.target.remove();},true);
document.addEventListener('change',event=>{const el=event.target;if(el.matches('[data-preview]')){const id=Number(el.dataset.preview);el.checked?U.previewMessageIds.add(id):U.previewMessageIds.delete(id)}if(el.matches('[data-composemedia]')){const id=Number(el.dataset.composemedia);el.checked?U.composeMedia.add(id):U.composeMedia.delete(id)}});
document.addEventListener('input',event=>{const el=event.target;if(el.id==='blur-slider'){U.blurStrength=Math.max(0,Math.min(32,Number(el.value)));document.getElementById('blur-value').textContent=U.blurStrength+'px';document.getElementById('page').style.setProperty('--blur-strength',U.blurStrength+'px');try{localStorage.setItem('telepilot_blur',String(U.blurStrength))}catch{}return;}if(el.matches('[data-live]')){const key=el.dataset.live;if(key==='network-search')U.search=el.value;if(key==='media-search')U.mediaSearch=el.value;if(key==='source-search')U.sourceSearch=el.value;const pos=el.selectionStart;render();const next=document.querySelector(`[data-live="${key}"]`);if(next){next.focus();next.setSelectionRange(pos,pos)}return}if(el.form?.id==='studio-form'&&el.name)U.draft[el.name]=el.value});
document.addEventListener('submit',event=>{event.preventDefault();const form=event.target,v=formValues(form),type=form.id;switch(type){
 case'download-form':break;
 case'community-form':run('create_community',{title:v.title,kind:v.kind,about:v.about||''});closeModal();break;
 case'partner-reply-form':{const message=String(v.message||'').trim();if(!message)return;run('partner_reply',{partner_id:Number(v.partner_id),text:message});form.reset();break}
 case'auth-form':{const cmd=event.submitter?.dataset.auth||'configure';if(cmd==='configure'){run('configure',{api_id:v.api_id,api_hash:v.api_hash,remember:v.remember});form.querySelector('[name=api_hash]').value=''}else if(cmd==='request_code'){run('request_code',{phone:v.phone})}else if(cmd==='sign_in'){run('sign_in',{code:v.code||'',password:v.password||''});if(form.querySelector('[name=code]'))form.querySelector('[name=code]').value='';if(form.querySelector('[name=password]'))form.querySelector('[name=password]').value=''}break}
 case'preferences-form':run('settings',{blur:Number(v.blur)});break;
 case'rules-form':run('settings',{send_interval:Number(v.send_interval),auto_watch:Number(v.auto_watch)});break;
 case'studio-form':{const mode=event.submitter?.dataset.mode||'draft',ids=[...U.composeMedia];if(!v.channel_id){toast('Sélectionnez un canal administré.',true);return}if(!v.text?.trim()&&!ids.length){toast('Ajoutez du texte ou un média.',true);return}const data={channel_id:Number(v.channel_id),text:v.text,media_ids:ids,due_at:mode==='scheduled'?new Date(v.due_at).getTime()/1000:null,draft:mode==='draft',credit:v.credit,allow_repeat:v.allow_repeat};if(mode!=='draft'){confirmAction(`Confirmer la publication sur le canal sélectionné ? ${ids.length} média(s), mode « ${mode==='now'?'maintenant':'programmé'} ».`,()=>{run('publish',data);U.composeMedia.clear();U.draft={};navigate('queue')})}else{run('publish',data);U.composeMedia.clear();U.draft={};navigate('queue')}break}
 case'assistant-form':{const name=v.partner||'à vous';const starts={Proposer:'Je vous propose un échange de visibilité entre nos canaux.',Négocier:'Merci pour votre proposition. Voici les conditions que je souhaite vous proposer.',Refuser:'Merci pour votre proposition. Je ne souhaite pas donner suite à cet échange.'};const msg=`Bonjour ${name},\n\n${starts[v.intent]||starts.Proposer}${v.intent!=='Refuser'?`\n\nDate envisagée : ${v.date||'à confirmer'}\nConditions : ${v.terms||'à préciser'}\n\nMerci de confirmer les textes, canaux et la durée avant tout accord.`:''}\n\nBonne journée.`;document.getElementById('assistant-output').value=msg;break}
 case'notes-form':run('channel_notes',{channel_id:Number(v.channel_id),category:v.category,notes:v.notes});closeModal();break;
 case'source-form':run('resolve_channel',{handle:v.handle});closeModal();break;
 case'network-form':run('network_link',{parent_id:Number(v.parent_id),child_id:Number(v.child_id),label:v.label||''});closeModal();break;
 case'partner-form':run('partner',{name:v.name,handle:v.handle,channel_id:v.channel_id?Number(v.channel_id):null,category:v.category,audience:Number(v.audience)||null,consent:v.consent,notes:v.notes,terms:v.terms});closeModal();break;
 case'exchange-form':run('exchange',{title:v.title,partner_id:Number(v.partner_id),channel_id:Number(v.channel_id),own_copy:v.own_copy,partner_copy:v.partner_copy,due_at:new Date(v.due_at).getTime()/1000,duration_hours:Number(v.duration_hours),terms:v.terms,expected_link:v.expected_link});closeModal();break;
 case'state-form':run('exchange_state',{exchange_id:Number(v.exchange_id),state:v.state});closeModal();break;
 case'review-form':run('approve_media',{media_id:Number(v.media_id),rights:v.rights,evidence:v.evidence,reviewed:v.reviewed,sensitive:v.sensitive,caption:v.caption});closeModal();break;
 case'resolve-form':{const ids=v.message_ids.split(',').map(s=>Number(s.trim()));if(!ids.length||ids.some(x=>!Number.isSafeInteger(x)||x<=0)){toast('Saisissez des IDs valides.',true);return}confirmAction('Je confirme avoir vérifié ces IDs sur Telegram.',()=>run('resolve',{task_id:v.task_id,message_ids:ids}));break}
 default:break;
 }});
// Gentle parallax limited to decorative elements; never moves inputs or cards.
if(!window.matchMedia('(prefers-reduced-motion: reduce)').matches){
  let lastMove=null, scheduled=false;
  window.addEventListener('pointermove',event=>{
    lastMove=event;
    if(scheduled)return;
    scheduled=true;
    requestAnimationFrame(()=>{
      scheduled=false;
      if(!lastMove)return;
      const x=(lastMove.clientX/window.innerWidth-.5),y=(lastMove.clientY/window.innerHeight-.5);
      document.querySelectorAll('[data-parallax]').forEach(el=>{
        const power=Number(el.dataset.parallax)||4;
        el.style.transform=`translate3d(${(x*power).toFixed(1)}px,${(y*power).toFixed(1)}px,0)`;
      });
    });
  },{passive:true});
}
document.getElementById('help-button').addEventListener('click',help);
document.getElementById('settings-button').addEventListener('click',()=>navigate('settings'));
document.querySelector('.sidebar-account').addEventListener('click',()=>navigate('settings'));
document.getElementById('modal-backdrop').addEventListener('click',event=>{if(event.target.id==='modal-backdrop')closeModal()});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!document.getElementById('modal-backdrop').classList.contains('hidden'))closeModal()});
render();loadState();setInterval(loadState,3500);
